head.script:
// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS11000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
    fn_CtrlBtn("no_data");
    await scwin.ins_Search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ISUR_CD_onclick
 * @description img_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISUR_CD_onclick = function() {
    try {
        ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS11000.img_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name dts_ApplInfo_OnLoadError
 * @description dts_ApplInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ApplInfo_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ApplInfo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS11000.dts_ApplInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ApplInfo_OnLoadCompleted
 * @description dts_ApplInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ApplInfo_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ApplInfo.errorMsg) {
            await $c.win.alert(dts_ApplInfo.errorMsg);
        }
        txb_TotalCnt.setValue("총 " + rowcount + "건");

        // 데이터가 없는 경우
        if (rowcount === 0) {
            fn_CtrlBtn("no_data");
        } else {
            fn_CtrlBtn("update");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS11000.dts_ApplInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ApplInfo_OnRowPosChanged
 * @description Appl Info On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ApplInfo_OnRowPosChanged = function(row) {
    try {
        // 미처리 인경우만 버튼 활성.
        if (row > 0 && dts_ApplInfo.getCellData(row, "APPL_PROCS_TP_CD") === "0") {
            fn_CtrlBtn("update");
        } else {
            fn_CtrlBtn("no_data");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS11000.dts_ApplInfo_OnRowPosChanged" });
    }
};

