/**
 * @method
 * @name grd_ApplInfo_OnDblClick
 * @description grd_ApplInfo 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ApplInfo_OnDblClick = async function(row, colid) {
    try {
        if (row === 0) return;
        if (colid === "ISU_NM") {
            const sStdCd = dts_ApplInfo.getCellData(row, "STD_CD");
            const sContnTpCd = dts_ApplInfo.getCellData(row, "STD_CD_APPL_CONTN_TP_CD"); // 상품구분
            const sContnTpCdTemp = dts_ApplInfo.getCellData(row, "STD_CD_APPL_CONTN_TP_CD_TEMP");
            let sKnd = "";
            if (sContnTpCd === "02") {
                sKnd = "주권";
            } else if (sContnTpCd === "10") {
                sKnd = "주식워런트";
            } else if (sContnTpCd === "11") {
                sKnd = "ELS_DLS";
            } else if (sContnTpCd === "12") {
                sKnd = "ETN";
            } else if (sContnTpCd === "77") {
                sKnd = "전자단기사채";
            }
            if (sContnTpCd === "08") {
                txb_param1.setValue(dts_ApplInfo.getCellData(row, "STD_CD"));
            } else {
                txb_param1.setValue(dts_ApplInfo.getCellData(row, "STD_CD"));
            }
            if (txb_param1.getValue() === "") {
                await $c.win.alert("삭제처리완료된 상품의 상세화면은 조회>표준코드삭제내역 에서 확인하세요.");
                return;
            }
            fn_GetPar = scwin.getParam;
            ins_ViewIsuMaster(sKnd, sStdCd);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS11000.grd_ApplInfo_OnDblClick" });
    }
};

