///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_Search
 * @description 삭제신청목록조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid("ins_Search")) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ApplInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ApplInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_Delete
 * @description 표준코드 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Delete = async function() {
    // 사전체크
    if (!await scwin.chkValid("ins_Delete")) {
        return;
    }
    let tmpMsg = "삭제시 관련기관의 데이터도 삭제되니 주의하시기 바랍니다.\n\n삭제 처리 하시겠습니까?";
    if (!confirm(tmpMsg)) {
        return;
    }

    // 선택된 Row만 서버로 전송..
    scwin.setTransData();
    trs_Delete.KeyName = "toinb_dataid4";
    // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/StdCdInfoListAction.do",
        ref : "dts_ApplInfo",
        target : "trs_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_Ret
 * @description 반송처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Ret = async function() {
    // 사전체크
    if (!await scwin.chkValid("ins_Ret")) {
        return;
    }
    let tmpMsg = "반송처리 하시겠습니까?";
    if (!confirm(tmpMsg)) {
        return;
    }

    // 선택된 Row만 서버로 전송..
    scwin.setTransData();
    trs_Ret.KeyName = "toinb_dataid4";
    // [전환검토] trs_Ret.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_Ret",
        action : "/StdCdInfoListAction.do",
        ref : "dts_ApplInfo",
        target : "trs_Ret=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {
    ins_combo_set(dts_STD_CD_APPL_CONTN_TP_CD, "ULDINS11000.xml", SCREN_PROCS_TP_CD_01, "03425", "ALL"); // 상품구분
    ins_combo_set(dts_APPL_PROCS_TP_CD, "ULDINS11000.xml", SCREN_PROCS_TP_CD_01, "03398", "ALL"); // 처리구분
    // dts_APPL_PROCS_TP_CD 필터링.(변경처리를 삭제하자.)
    let nRow = $c.cp.getNameValueRow(dts_APPL_PROCS_TP_CD, "VALUE", "1");
    dts_APPL_PROCS_TP_CD.removeRow(nRow);
};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FROM_STD_CD_APPL_DD.setValue(vCurDate);
    //    edt_FROM_STD_CD_APPL_DD.Text = vCurDate.substr(0, 6) + "01";
    edt_TO_STD_CD_APPL_DD.setValue(vCurDate);
    const array_grid = [grd_ApplInfo];
    setResizeGrid(array_grid);
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_ApplInfo.removeAll();
    txb_TotalCnt.setValue("총 0건");
};

/**
 * @method
 * @name setTransData
 * @description 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 * @returns {void}
 * @hidden N
 */
scwin.setTransData = function() {
    let nRow = dts_ApplInfo.getRowPosition();
    dts_ApplInfo.setCellData(nRow, "CHK", "T");
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === undefined) {
        return true;
    }
    if (pGubun === "ins_Search") {
        if (edt_FROM_STD_CD_APPL_DD.getValue() === "") {
            await $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
        if (edt_TO_STD_CD_APPL_DD.getValue() === "") {
            await $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_STD_CD_APPL_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD, edt_TO_STD_CD_APPL_DD) === false) {
            return false;
        }
    } else if (pGubun === "ins_Delete") {
        if (!fn_checkSendTime(dts_time, "ULDINS11000.xml")) {
            await $c.win.alert("정보문의 전송 마감시간(19:00)이 초과되어 삭제하실수 없습니다.");
            return false;
        }
        // 스트립인경우.
        if (dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "STD_CD_APPL_CONTN_TP_CD") === "8") {
            await $c.win.alert("시스템 담당자에게 연락바랍니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name getParam
 * @description 발생기관 팝업에서 값 받음.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue();
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};
